import requests
qs=['"naringin" "pancreatic beta-cell" protease inhibitor','naringin HIV protease inhibitor pancreatic beta cell apoptosis','naringin indinavir beta-cell dysfunction','"HIV-1 protease inhibitors-induced" naringin']
for q in qs:
 d=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':10,'resultType':'core'},timeout=20).json()
 print('\nQUERY',q,'HITS',d.get('hitCount'))
 for x in d.get('resultList',{}).get('result',[]):
  print(x.get('pmid'),x.get('title'),x.get('pubYear'),x.get('doi'))
  a=x.get('abstractText') or ''
  if a: print(a[:1600])
